window.kbPageData["views/entry/k-84201ae4d61b6f0c"] = {"key":"entry/k-84201ae4d61b6f0c","state":{"route":"entry/k-84201ae4d61b6f0c"},"node":{"id":"k-84201ae4d61b6f0c","mode":"k","title":"点集的凸包","type":"概念与词义","domain":"数学","reading":"","intro":"","priority":100,"aliases":["点集的凸包是包含全部点的最小凸集"],"qs":["国考 2023 副省级 行测#94"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"点集的凸包是包含该点集全部点的最小凸集，且包含于任何覆盖这些点的凸集中。对于有限个不全共线的平面点，凸包是由最外围的若干点围成的凸多边形及其内部。","review":{"definition":"点集的凸包是包含该点集全部点的最小凸集，且包含于任何覆盖这些点的凸集中。对于有限个不全共线的平面点，凸包是由最外围的若干点围成的凸多边形及其内部。","explanation":"第94题用黑色方块表示生物已知、推断或预计出现的位点，并用这些位点的凸包表示分布区。A把所有位点纳入边界或内部，每个内角都不超过180度，边界也无法在保持覆盖的前提下继续收紧。B有内凹处，C的右侧漏掉一个位点，D的左下角和右侧尖角还能向内收紧，因此选A。","references":[],"evidence":"该最小凸边形的每个内角不能超过180度，并要包含所有出现的位点。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2023 副省级 行测#94":{"paper":"国考 2023 副省级 行测","n":94,"mod":"判断推理","src":["503793642e845de9795f.pdf",20],"asrc":["ecade1ff5af69283232e.pdf",29],"card":"7cdaef9aabf2dce2d0ce877e","links":[{"id":"k-84201ae4d61b6f0c","role":"解题依据","why":"题中的最小凸边形是这些位点的凸包，检验时须兼顾全覆盖、凸性和最小性。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-84201ae4d61b6f0c":[["国考 2023 副省级 行测#94"]]}};
